/* Run in the active native fixture generated by view-transition-benchmark.mjs. */
window.runGlassViewTransitionProbe = async function () {
  const api = window.GlassContinuity, card = document.createElement('div');
  card.style.cssText = 'width:180px;height:180px;background:#254ae9;border-radius:24px';
  document.body.append(card);
  const name = api.nameGlassView(card, 'fixture-probe');
  const oldRaf = window.requestAnimationFrame, oldRect = Element.prototype.getBoundingClientRect;
  let callbacks = 0, customRafRequests = 0, jsRectangleReads = 0;
  window.requestAnimationFrame = (...args) => { customRafRequests++; return oldRaf.apply(window, args); };
  Element.prototype.getBoundingClientRect = function (...args) { jsRectangleReads++; return oldRect.apply(this, args); };
  const commit = () => { callbacks++; card.style.marginLeft = callbacks % 2 ? '300px' : '0px'; };
  try {
    const runs = [];
    for (let i = 0; i < 5; i++) {
      const start = performance.now(), handle = api.runGlassViewTransition(commit, { duration: 220 });
      const ready = await handle.ready;
      const animations = document.getAnimations().filter(a => a.playState === 'running').map(a => ({ name: a.animationName, pseudo: a.effect?.pseudoElement }));
      const result = await handle.finished;
      runs.push({ native: handle.native, ready, animations, result, completionMs: performance.now() - start });
    }
    const directResult = await api.runGlassViewTransition(commit, { reducedMotion: true }).finished;
    const burst = Array.from({ length: 20 }, () => api.runGlassViewTransition(commit));
    const burstResults = await Promise.all(burst.map(handle => handle.finished));
    if (callbacks !== 26) throw Error(`Expected 26 host commits, received ${callbacks}`);
    return { observedAtUtc: new Date().toISOString(), browser: navigator.userAgent, dpr: devicePixelRatio, viewport: [innerWidth, innerHeight], runs, directResult, burstResults, callbacks, expectedCallbacks: 26, customRafRequests, jsRectangleReads, remainingAnimations: document.getAnimations().filter(a => a.playState === 'running').length, scope: 'Actual native readiness/completion/callback integrity. Completion includes explicit duration and native snapshots; not bridge CPU, FPS, GPU or comparative speedup.' };
  } finally {
    window.requestAnimationFrame = oldRaf; Element.prototype.getBoundingClientRect = oldRect; name.destroy(); card.remove();
  }
};
